import { auth, currentUser as clerkCurrentUser } from "@clerk/nextjs/server";

export type User = {
  id: string;
  email: string;
  name: string;
  createdAt: string;
};

const users: User[] = [
  { id: "1", email: "ada@example.com", name: "Ada", createdAt: "2026-01-04" },
  { id: "2", email: "grace@example.com", name: "Grace", createdAt: "2026-02-11" },
];

export async function listUsers(): Promise<User[]> {
  return users;
}

export async function getUser(id: string): Promise<User | undefined> {
  return users.find((u) => u.id === id);
}

// Backed by the real Clerk session now. Clerk's userId becomes our User.id,
// and the first time we see a given signed-in user we sync a record into the
// in-memory store so the rest of the app (e.g. the team list) can keep
// treating `User` as the single source of truth.
export async function getCurrentUser(): Promise<User | undefined> {
  const { userId } = await auth();
  if (!userId) return undefined;

  const existing = users.find((u) => u.id === userId);
  if (existing) return existing;

  const clerkUser = await clerkCurrentUser();
  if (!clerkUser) return undefined;

  const synced: User = {
    id: userId,
    email: clerkUser.primaryEmailAddress?.emailAddress ?? clerkUser.emailAddresses[0]?.emailAddress ?? "",
    name:
      [clerkUser.firstName, clerkUser.lastName].filter(Boolean).join(" ") ||
      clerkUser.username ||
      "New user",
    createdAt: new Date(clerkUser.createdAt ?? Date.now()).toISOString().slice(0, 10),
  };
  users.push(synced);
  return synced;
}

