import { clerkMiddleware } from "@clerk/nextjs/server";

// Establishes the Clerk auth context for every request so `auth()` /
// `currentUser()` work in Server Components, route handlers, etc.
// Actual access control lives on the protected pages themselves (see
// src/app/dashboard/page.tsx) — Clerk now recommends resource-based checks
// over path-matching middleware, since middleware matching can drift from
// how Next.js actually routes a request.
export default clerkMiddleware();

export const config = {
  matcher: [
    // Skip Next.js internals and static files, unless found in search params
    "/((?!_next|[^?]*\\.(?:html?|css|js(?!on)|jpe?g|webp|avif|png|gif|svg|ttf|woff2?|ico|csv|docx?|xlsx?|zip|webmanifest)).*)",
    "/(api|trpc)(.*)",
  ],
};

